interactions.sample_code:
function merge(left, right) {
  // walk both runs, always taking the smaller front
  while (remaining(left) > 0 && remaining(right) > 0) {
    if (frontLessEqual(left, right)) {
      take(left);   // ties go LEFT -> stable
    } else {
      take(right);
    }
  }
  // one run is exhausted; drain the other
  while (remaining(left) > 0) take(left);
  while (remaining(right) > 0) take(right);
}

